var toggle = document.getElementById('sort-toggle')
var list = document.getElementById('sort-list')
var label = document.getElementById('sort-label')
var options = Array.prototype.slice.call(document.querySelectorAll('.dd-option'))

function isOpen () {
  return list.classList.contains('open')
}

function openList () {
  list.classList.add('open')
  toggle.setAttribute('aria-expanded', 'true')
  var selected = options.filter(function (o) { return o.getAttribute('aria-selected') === 'true' })[0]
  ;(selected || options[0]).focus()
}

function closeList (returnFocus) {
  list.classList.remove('open')
  toggle.setAttribute('aria-expanded', 'false')
  if (returnFocus) toggle.focus()
}

function selectOption (option) {
  options.forEach(function (o) { o.setAttribute('aria-selected', 'false') })
  option.setAttribute('aria-selected', 'true')
  label.textContent = 'Sort: ' + option.getAttribute('data-value')
  closeList(true)
}

toggle.addEventListener('click', function () {
  if (isOpen()) {
    closeList(false)
  } else {
    openList()
  }
})

toggle.addEventListener('keydown', function (e) {
  if ((e.key === 'ArrowDown' || e.key === 'ArrowUp') && !isOpen()) {
    e.preventDefault()
    openList()
  }
})

options.forEach(function (option, index) {
  option.addEventListener('click', function () {
    selectOption(option)
  })
  option.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowDown') {
      e.preventDefault()
      ;(options[index + 1] || options[0]).focus()
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      ;(options[index - 1] || options[options.length - 1]).focus()
    } else if (e.key === 'Home') {
      e.preventDefault()
      options[0].focus()
    } else if (e.key === 'End') {
      e.preventDefault()
      options[options.length - 1].focus()
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      selectOption(option)
    } else if (e.key === 'Escape') {
      e.preventDefault()
      closeList(true)
    } else if (e.key === 'Tab') {
      closeList(false)
    }
  })
})

